package com.zineb.chat.server.app;
import com.zineb.chat.server.controller.ServerController; import com.zineb.chat.server.view.ServerView; import javafx.application.Application; import javafx.scene.Scene; import javafx.stage.Stage; import java.util.Objects;
public final class TCPServerApp extends Application { private ServerController controller; public void start(Stage stage){ServerView view=new ServerView();controller=new ServerController(view);Scene scene=new Scene(view.root(),850,560);scene.getStylesheets().add(Objects.requireNonNull(getClass().getResource("/server.css")).toExternalForm());stage.setTitle("TCPServer - Zineb Maimmadi");stage.setScene(scene);stage.show();controller.start();} public void stop(){if(controller!=null)controller.stop();} public static void main(String[]a){launch(a);} }
